WITH r AS (
  SELECT user_id, payment_id, paid_at, amount,
         RANK() OVER (PARTITION BY user_id ORDER BY paid_at) AS rk
  FROM payments
)
SELECT user_id, payment_id, paid_at, amount FROM r WHERE rk = 3 ORDER BY user_id;

WITH r AS (
  SELECT user_id, payment_id, paid_at, amount,
         ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY payment_id) AS rn
  FROM payments
)
SELECT user_id, payment_id, paid_at, amount FROM r WHERE rn = 3 ORDER BY user_id;

