WITH RECURSIVE bounds AS (
  SELECT MIN(sale_date) AS first_d, MAX(sale_date) AS last_d FROM store_sales
), spine AS (
  SELECT first_d AS d FROM bounds
  UNION ALL
  SELECT DATE_ADD(s.d, INTERVAL 1 DAY) FROM spine s, bounds b WHERE s.d < b.last_d
), daily AS (
  SELECT sale_date, SUM(amount) AS rev FROM store_sales GROUP BY sale_date
), filled AS (
  SELECT s.d AS sale_date, COALESCE(dl.rev, 0) AS daily_revenue
  FROM spine s LEFT JOIN daily dl ON dl.sale_date = s.d
)
SELECT sale_date, daily_revenue,
       SUM(daily_revenue) OVER (ORDER BY sale_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS rolling_7d_revenue
FROM filled
ORDER BY sale_date;

