WITH t AS (
  SELECT emp_id, name, salary,
         NTILE(10) OVER (ORDER BY salary DESC, emp_id) AS decile
  FROM staff
)
SELECT emp_id, name, salary FROM t WHERE decile = 1 ORDER BY salary DESC, emp_id;
